//! RAR4 / RAR5 reading through `ExtractionSink`.
//!
//! The `tests/corpus/rar*` fixtures are generated by `regenerate_rar_corpus` (run it with
//! `cargo test -p dandi-core --test rar_read -- --ignored`) using the pure-Rust `rars` writer and
//! are cross-checked against libarchive (`bsdtar`), an independent RAR reader.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use dandi_core::{
    inspect, unpack, ArchiveFormat, DandiError, EncodingId, EntryKind, ExtractMode, InspectOptions,
    NoopProgressObserver, SafetyBudget, UnpackOptions,
};
use sha2::{Digest, Sha256};
use tempfile::TempDir;
use unicode_normalization::UnicodeNormalization;

const RAR_PW: &str = "단디-rar!2026";
const MTIME: i64 = 1_767_225_600; // 2026-01-01T00:00:00Z

fn corpus(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/corpus")
        .join(name)
}

fn pseudo_random(len: usize, seed: u64) -> Vec<u8> {
    let mut state = seed | 1;
    (0..len)
        .map(|_| {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            (state >> 24) as u8
        })
        .collect()
}

/// Files every "basic" fixture contains, as (archive path, bytes).
fn basic_payload() -> Vec<(&'static str, Vec<u8>)> {
    vec![
        ("bundle/hello.txt", b"Hello from a RAR fixture\n".to_vec()),
        (
            "bundle/nested/한글_문서.txt",
            "단디는 RAR 도 안전하게 풉니다\n".repeat(40).into_bytes(),
        ),
        ("bundle/nested/がぎぐ.txt", "かな\n".repeat(10).into_bytes()),
        (
            "bundle/log.txt",
            b"2026-01-01 INFO compressible line\n".repeat(120),
        ),
        ("bundle/noise.bin", pseudo_random(700, 11)),
        ("bundle/run.sh", b"#!/bin/sh\necho dandi\n".to_vec()),
    ]
}

fn sha(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

fn hash_tree(root: &Path) -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    for entry in walkdir::WalkDir::new(root) {
        let entry = entry.unwrap();
        if entry.file_type().is_file() {
            let rel = entry
                .path()
                .strip_prefix(root)
                .unwrap()
                .to_string_lossy()
                .replace('\\', "/");
            // macOS bsdtar writes names as NFD.
            out.insert(rel.nfc().collect(), sha(&fs::read(entry.path()).unwrap()));
        }
    }
    out
}

fn expected_basic() -> BTreeMap<String, String> {
    basic_payload()
        .into_iter()
        .map(|(p, b)| (p.to_string(), sha(&b)))
        .collect()
}

fn direct(password: Option<&str>) -> UnpackOptions {
    UnpackOptions {
        mode: ExtractMode::Direct,
        password: password.map(str::to_string),
        ..UnpackOptions::default()
    }
}

// ---------------------------------------------------------------------------------------------
// Fixture generation
// ---------------------------------------------------------------------------------------------

mod gen {
    use super::*;
    use rars::{ArchiveVersion, Builder, Timestamp};

    fn basic(version: ArchiveVersion) -> Builder {
        let ts = Some(Timestamp::from_unix_seconds(MTIME));
        let mut b = Builder::new(version);
        b.add_directory(b"bundle".to_vec(), ts, Some(0o755))
            .unwrap();
        b.add_directory(b"bundle/nested".to_vec(), ts, Some(0o755))
            .unwrap();
        for (name, data) in basic_payload() {
            let mode = if name.ends_with(".sh") { 0o755 } else { 0o644 };
            b.add_bytes(name.as_bytes().to_vec(), data, ts, Some(mode))
                .unwrap();
        }
        b
    }

    /// Rewrites `from` to `to` (same length) inside one block header and fixes that header's
    /// CRC, producing names the `rars` builder refuses to write (e.g. `../evil.txt`).
    fn patch_name(mut bytes: Vec<u8>, from: &[u8], to: &[u8], rar5: bool) -> Vec<u8> {
        assert_eq!(from.len(), to.len());
        let name_at = bytes
            .windows(from.len())
            .position(|w| w == from)
            .expect("name present");
        let (start, crc_len) = (8..name_at)
            .rev()
            .find_map(|p| header_span(&bytes, p, rar5).filter(|(_, end)| *end > name_at))
            .expect("header containing the name");
        bytes[name_at..name_at + to.len()].copy_from_slice(to);
        if rar5 {
            let crc = crc32fast::hash(&bytes[start + 4..crc_len]);
            bytes[start..start + 4].copy_from_slice(&crc.to_le_bytes());
        } else {
            let crc = (crc32fast::hash(&bytes[start + 2..crc_len]) & 0xFFFF) as u16;
            bytes[start..start + 2].copy_from_slice(&crc.to_le_bytes());
        }
        bytes
    }

    /// Returns `(header_start, header_end)` when a valid block header begins at `p`.
    fn header_span(bytes: &[u8], p: usize, rar5: bool) -> Option<(usize, usize)> {
        if rar5 {
            let stored = u32::from_le_bytes(bytes.get(p..p + 4)?.try_into().ok()?);
            let (size, vlen) = read_vint(bytes.get(p + 4..)?)?;
            let end = p + 4 + vlen + usize::try_from(size).ok()?;
            (end <= bytes.len() && crc32fast::hash(&bytes[p + 4..end]) == stored)
                .then_some((p, end))
        } else {
            let stored = u16::from_le_bytes(bytes.get(p..p + 2)?.try_into().ok()?);
            let size = u16::from_le_bytes(bytes.get(p + 5..p + 7)?.try_into().ok()?) as usize;
            let end = p + size;
            (size >= 7
                && end <= bytes.len()
                && (crc32fast::hash(&bytes[p + 2..end]) & 0xFFFF) as u16 == stored)
                .then_some((p, end))
        }
    }

    fn read_vint(buf: &[u8]) -> Option<(u64, usize)> {
        let mut value = 0u64;
        for (i, b) in buf.iter().take(10).enumerate() {
            value |= u64::from(b & 0x7F) << (7 * i);
            if b & 0x80 == 0 {
                return Some((value, i + 1));
            }
        }
        None
    }

    pub fn write_all(dir: &Path) {
        let ts = Some(Timestamp::from_unix_seconds(MTIME));
        fs::create_dir_all(dir).unwrap();
        let put = |name: &str, bytes: Vec<u8>| fs::write(dir.join(name), bytes).unwrap();

        put(
            "rar4_basic.rar",
            basic(ArchiveVersion::Rar29).to_bytes().unwrap(),
        );

        let mut rar5 = basic(ArchiveVersion::Rar50);
        rar5.add_unix_symlink(
            b"bundle/latest.txt".to_vec(),
            b"hello.txt".to_vec(),
            false,
            ts,
            None,
        )
        .unwrap();
        put("rar5_basic.rar", rar5.to_bytes().unwrap());

        // RAR4 names without the Unicode flag are raw bytes in the packer's ANSI code page.
        let mut cp949 = Builder::new(ArchiveVersion::Rar29);
        for (name, data) in [
            ("자료/회의록.txt", "회의록"),
            ("자료/보고서_최종.txt", "보고서"),
            ("자료/한글파일.txt", "한글"),
        ] {
            let (raw, _, _) = encoding_rs::EUC_KR.encode(name);
            cp949
                .add_bytes(raw.into_owned(), data.as_bytes().to_vec(), ts, None)
                .unwrap();
        }
        put("rar4_cp949_names.rar", cp949.to_bytes().unwrap());

        let mut enc = basic(ArchiveVersion::Rar50)
            .password(Some(RAR_PW.as_bytes().to_vec()))
            .header_encryption(true);
        enc = enc.compression_level(Some(3));
        put("rar5_encrypted.rar", enc.to_bytes().unwrap());

        let mut bomb = Builder::new(ArchiveVersion::Rar50);
        bomb.add_bytes(b"zeros.bin".to_vec(), vec![0u8; 8 << 20], ts, None)
            .unwrap();
        put("rar5_zero_bomb.rar", bomb.to_bytes().unwrap());

        for (file, version, rar5) in [
            ("rar5_zip_slip.rar", ArchiveVersion::Rar50, true),
            ("rar4_zip_slip.rar", ArchiveVersion::Rar29, false),
        ] {
            let mut slip = Builder::new(version);
            slip.add_bytes(b"safe.txt".to_vec(), b"safe".to_vec(), ts, None)
                .unwrap();
            slip.add_bytes(b"zz/evil.txt".to_vec(), b"pwned".to_vec(), ts, None)
                .unwrap();
            let bytes = slip.to_bytes().unwrap();
            put(
                file,
                patch_name(bytes, b"zz/evil.txt", b"../evil.txt", rar5),
            );
        }

        let mut multi = Builder::new(ArchiveVersion::Rar50).volume_size(Some(2 * 1024));
        multi
            .add_bytes(b"big/part.bin".to_vec(), pseudo_random(5000, 5), ts, None)
            .unwrap();
        multi
            .add_bytes(
                b"big/note.txt".to_vec(),
                b"after the split".to_vec(),
                ts,
                None,
            )
            .unwrap();
        for (i, vol) in multi.build_volumes(None).unwrap().into_iter().enumerate() {
            put(&format!("rar5_multi.part{}.rar", i + 1), vol);
        }
    }
}

#[test]
#[ignore = "regenerates committed fixtures; run manually after changing the generator"]
fn regenerate_rar_corpus() {
    gen::write_all(&corpus(""));
}

// ---------------------------------------------------------------------------------------------
// Reading
// ---------------------------------------------------------------------------------------------

#[test]
fn rar4_and_rar5_inspect_and_unpack_through_the_sink() {
    for fixture in ["rar4_basic.rar", "rar5_basic.rar"] {
        let path = corpus(fixture);
        let summary = inspect(&path, &InspectOptions::default()).unwrap();
        assert_eq!(summary.format, ArchiveFormat::Rar, "{fixture}");
        assert!(!summary.encrypted);
        let paths: Vec<&str> = summary.entries.iter().map(|e| e.path.as_str()).collect();
        for (name, _) in basic_payload() {
            assert!(
                paths.contains(&name),
                "{fixture}: {name} missing from {paths:?}"
            );
        }
        let method = &summary
            .entries
            .iter()
            .find(|e| e.path == "bundle/log.txt")
            .unwrap()
            .compression_method;
        assert!(method.starts_with(if fixture.starts_with("rar4") {
            "rar4"
        } else {
            "rar5"
        }));

        let tmp = TempDir::new().unwrap();
        let report = unpack(&path, tmp.path(), &direct(None), &NoopProgressObserver).unwrap();
        assert_eq!(report.format, ArchiveFormat::Rar);
        let got = hash_tree(tmp.path());
        for (name, digest) in expected_basic() {
            assert_eq!(got.get(&name), Some(&digest), "{fixture}: {name}");
        }
        let modified = fs::metadata(tmp.path().join("bundle/hello.txt"))
            .unwrap()
            .modified()
            .unwrap()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs() as i64;
        assert!((modified - MTIME).abs() <= 2, "{fixture}: mtime {modified}");
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = fs::metadata(tmp.path().join("bundle/run.sh"))
                .unwrap()
                .permissions()
                .mode();
            assert_eq!(mode & 0o111, 0o111, "{fixture}: exec bit lost ({mode:o})");
        }
    }
}

#[cfg(unix)]
#[test]
fn rar5_relative_symlink_is_materialized_inside_destination() {
    let tmp = TempDir::new().unwrap();
    let report = unpack(
        &corpus("rar5_basic.rar"),
        tmp.path(),
        &direct(None),
        &NoopProgressObserver,
    )
    .unwrap();
    assert_eq!(report.symlinks_created, 1, "{report:?}");
    assert_eq!(
        fs::read_link(tmp.path().join("bundle/latest.txt")).unwrap(),
        PathBuf::from("hello.txt")
    );
    let summary = inspect(&corpus("rar5_basic.rar"), &InspectOptions::default()).unwrap();
    let link = summary
        .entries
        .iter()
        .find(|e| e.path == "bundle/latest.txt")
        .unwrap();
    assert_eq!(link.kind, EntryKind::Symlink);
}

#[test]
fn rar4_legacy_names_are_detected_as_cp949_and_nfc() {
    let path = corpus("rar4_cp949_names.rar");
    let summary = inspect(&path, &InspectOptions::default()).unwrap();
    assert_eq!(
        summary.encoding.encoding,
        EncodingId::Cp949,
        "{:?}",
        summary.encoding
    );
    let paths: Vec<&str> = summary.entries.iter().map(|e| e.path.as_str()).collect();
    assert!(paths.contains(&"자료/회의록.txt"), "{paths:?}");

    let tmp = TempDir::new().unwrap();
    let report = unpack(&path, tmp.path(), &direct(None), &NoopProgressObserver).unwrap();
    assert_eq!(report.applied_encoding, EncodingId::Cp949);
    assert_eq!(
        fs::read_to_string(tmp.path().join("자료/보고서_최종.txt")).unwrap(),
        "보고서"
    );
}

#[test]
fn zip_slip_entries_are_rejected_with_zero_writes() {
    for fixture in ["rar5_zip_slip.rar", "rar4_zip_slip.rar"] {
        let tmp = TempDir::new().unwrap();
        let dest = tmp.path().join("dest");
        fs::create_dir_all(&dest).unwrap();
        let err = unpack(
            &corpus(fixture),
            &dest,
            &direct(None),
            &NoopProgressObserver,
        )
        .unwrap_err();
        assert!(
            matches!(err, DandiError::UnsafePath { .. }),
            "{fixture}: {err:?}"
        );
        assert!(!tmp.path().join("evil.txt").exists(), "{fixture} escaped");
        assert!(
            !dest.join("safe.txt").exists(),
            "{fixture} wrote before failing"
        );
    }
}

#[test]
fn overwrite_false_keeps_existing_files() {
    let tmp = TempDir::new().unwrap();
    let path = corpus("rar5_basic.rar");
    unpack(&path, tmp.path(), &direct(None), &NoopProgressObserver).unwrap();
    let hello = tmp.path().join("bundle/hello.txt");
    fs::write(&hello, b"user edit").unwrap();
    let err = unpack(&path, tmp.path(), &direct(None), &NoopProgressObserver).unwrap_err();
    assert!(matches!(err, DandiError::AlreadyExists { .. }), "{err:?}");
    assert_eq!(fs::read(&hello).unwrap(), b"user edit");
}

#[test]
fn safety_budget_stops_rar_zero_bomb() {
    let path = corpus("rar5_zero_bomb.rar");
    assert!(fs::metadata(&path).unwrap().len() < 64 * 1024);
    let tmp = TempDir::new().unwrap();
    let dest = tmp.path().join("bomb");
    let err = unpack(
        &path,
        &dest,
        &UnpackOptions {
            budget: SafetyBudget::new(1 << 20, 100, 200.0, 64 * 1024),
            ..direct(None)
        },
        &NoopProgressObserver,
    )
    .unwrap_err();
    assert!(matches!(err, DandiError::BudgetExceeded { .. }), "{err:?}");
    assert!(!dest.exists(), "partial bomb output left behind");
}

#[test]
fn encrypted_rar5_requires_the_right_password() {
    let path = corpus("rar5_encrypted.rar");
    let none = inspect(&path, &InspectOptions::default());
    assert!(
        matches!(none, Err(DandiError::PasswordRequired)),
        "{none:?}"
    );
    let wrong = inspect(
        &path,
        &InspectOptions {
            password: Some("wrong".to_string()),
            ..InspectOptions::default()
        },
    );
    assert!(
        matches!(wrong, Err(DandiError::InvalidPassword)),
        "{wrong:?}"
    );

    let tmp = TempDir::new().unwrap();
    let bad_dest = tmp.path().join("bad");
    let bad = unpack(
        &path,
        &bad_dest,
        &direct(Some("wrong")),
        &NoopProgressObserver,
    );
    assert!(matches!(bad, Err(DandiError::InvalidPassword)), "{bad:?}");
    assert!(!bad_dest.exists());

    let ok = tmp.path().join("ok");
    unpack(&path, &ok, &direct(Some(RAR_PW)), &NoopProgressObserver).unwrap();
    let got = hash_tree(&ok);
    for (name, digest) in expected_basic() {
        assert_eq!(got.get(&name), Some(&digest), "{name}");
    }
}

#[test]
fn multi_volume_rar_opens_from_any_part_and_names_missing_parts() {
    let tmp = TempDir::new().unwrap();
    let mut parts: Vec<PathBuf> = (1..)
        .map(|i| corpus(&format!("rar5_multi.part{i}.rar")))
        .take_while(|p| p.exists())
        .collect();
    assert!(parts.len() >= 3, "{parts:?}");
    for p in parts.iter_mut() {
        let copy = tmp.path().join(p.file_name().unwrap());
        fs::copy(&*p, &copy).unwrap();
        *p = copy;
    }

    for opener in [&parts[0], &parts[1]] {
        let dest = tmp.path().join(format!(
            "x_{}",
            opener.file_name().unwrap().to_string_lossy()
        ));
        unpack(opener, &dest, &direct(None), &NoopProgressObserver).unwrap();
        assert_eq!(
            fs::read(dest.join("big/part.bin")).unwrap(),
            pseudo_random(5000, 5)
        );
        assert_eq!(
            fs::read(dest.join("big/note.txt")).unwrap(),
            b"after the split"
        );
    }

    fs::remove_file(&parts[1]).unwrap();
    let dest = tmp.path().join("missing");
    match unpack(&parts[0], &dest, &direct(None), &NoopProgressObserver) {
        Err(DandiError::CorruptArchive(msg)) => {
            assert!(msg.contains("part2") || msg.contains("volume 2"), "{msg}")
        }
        other => panic!("expected missing-volume error, got {other:?}"),
    }
    assert!(!dest.exists());
}

#[test]
fn truncated_and_garbage_rar_return_structured_errors() {
    let tmp = TempDir::new().unwrap();
    let bytes = fs::read(corpus("rar5_basic.rar")).unwrap();
    let truncated = tmp.path().join("truncated.rar");
    fs::write(&truncated, &bytes[..bytes.len() / 2]).unwrap();
    let garbage = tmp.path().join("garbage.rar");
    let mut junk = b"Rar!\x1a\x07\x01\x00".to_vec();
    junk.extend(pseudo_random(4096, 99));
    fs::write(&garbage, &junk).unwrap();

    for path in [&truncated, &garbage] {
        let dest = tmp.path().join("out");
        let err = unpack(path, &dest, &direct(None), &NoopProgressObserver).unwrap_err();
        assert!(
            matches!(
                err,
                DandiError::CorruptArchive(_) | DandiError::UnsupportedFormat(_)
            ),
            "{path:?}: {err:?}"
        );
        assert!(!dest.exists(), "{path:?} left output");
    }
}

/// libarchive is an independent RAR4/RAR5 decoder: it must agree byte-for-byte.
#[test]
fn bsdtar_agrees_with_committed_rar_fixtures() {
    let Ok(probe) = Command::new("bsdtar").arg("--version").output() else {
        eprintln!("skipping: bsdtar not installed");
        return;
    };
    if !probe.status.success() {
        eprintln!("skipping: bsdtar not usable");
        return;
    }
    for fixture in ["rar4_basic.rar", "rar5_basic.rar"] {
        let tmp = TempDir::new().unwrap();
        let status = Command::new("bsdtar")
            .arg("-xf")
            .arg(corpus(fixture))
            .arg("-C")
            .arg(tmp.path())
            .status()
            .unwrap();
        assert!(status.success(), "bsdtar failed on {fixture}");
        let got = hash_tree(tmp.path());
        for (name, digest) in expected_basic() {
            assert_eq!(got.get(&name), Some(&digest), "bsdtar {fixture}: {name}");
        }
    }
}

#[test]
fn selective_rar_extraction_writes_only_chosen_entries() {
    let path = corpus("rar5_basic.rar");
    let summary = inspect(&path, &InspectOptions::default()).unwrap();
    let pick = |p: &str| {
        summary
            .entries
            .iter()
            .find(|e| e.path == p)
            .and_then(|e| e.index)
            .unwrap()
    };
    let tmp = TempDir::new().unwrap();
    unpack(
        &path,
        tmp.path(),
        &UnpackOptions {
            selected_entries: Some(
                [pick("bundle/log.txt"), pick("bundle/nested/한글_문서.txt")]
                    .into_iter()
                    .collect(),
            ),
            ..direct(None)
        },
        &NoopProgressObserver,
    )
    .unwrap();
    let got: Vec<String> = hash_tree(tmp.path()).into_keys().collect();
    assert_eq!(got, vec!["bundle/log.txt", "bundle/nested/한글_문서.txt"]);
}

/// A member whose data fails its CRC must not survive, even inside a pre-existing folder that
/// Dandi will not clean up.
#[test]
fn rar_member_failing_crc_is_not_kept() {
    let tmp = TempDir::new().unwrap();
    let mut bytes = fs::read(corpus("rar4_basic.rar")).unwrap();
    // `noise.bin` is incompressible, so its payload is stored verbatim and easy to corrupt.
    let noise = pseudo_random(700, 11);
    let at = bytes
        .windows(64)
        .position(|w| w == &noise[..64])
        .expect("stored payload");
    bytes[at + 350] ^= 0xFF;
    let path = tmp.path().join("crc.rar");
    fs::write(&path, &bytes).unwrap();

    let dest = tmp.path().join("dest");
    fs::create_dir_all(&dest).unwrap();
    let err = unpack(&path, &dest, &direct(None), &NoopProgressObserver).unwrap_err();
    assert!(matches!(err, DandiError::CorruptArchive(_)), "{err:?}");
    assert!(
        !dest.join("bundle/noise.bin").exists(),
        "corrupt member kept"
    );
}
